88	    void CaresPTRResolver::wait()
89	    {
90	        timeval * tvp, tv;
91	        fd_set read_fds;
92	        fd_set write_fds;
93	        int nfds;
94	
95	        for (;;)
96	        {
97	            FD_ZERO(&read_fds);
98	            FD_ZERO(&write_fds);
99	            nfds = ares_fds(channel, &read_fds,&write_fds);
100	            if (nfds == 0)
101	            {
102	                break;
103	            }
104	            tvp = ares_timeout(channel, nullptr, &tv);
105	            select(nfds, &read_fds, &write_fds, nullptr, tvp);
106	            ares_process(channel, &read_fds, &write_fds);
107	        }
