726	bool CachedReadBufferFromRemoteFS::nextImpl()
727	{
728	    try
729	    {
730	        return nextImplStep();
731	    }
732	    catch (Exception & e)
733	    {
734	        e.addMessage("Cache info: {}", nextimpl_step_log_info);
735	        throw;
736	    }
737	}
738	
739	bool CachedReadBufferFromRemoteFS::nextImplStep()
740	{
741	    last_caller_id = FileSegment::getCallerId();
742	
743	    assertCorrectness();
744	
745	    if (!initialized)
746	        initialize(file_offset_of_buffer_end, getTotalSizeToRead());
747	
748	    if (current_file_segment_it == file_segments_holder->file_segments.end())
749	        return false;
750	
751	    SCOPE_EXIT({
752	        try
753	        {
754	            /// Save state of current file segment before it is completed.
755	            nextimpl_step_log_info = getInfoForLog();
756	
757	            if (current_file_segment_it == file_segments_holder->file_segments.end())
758	                return;
759	
760	            auto & file_segment = *current_file_segment_it;
761	
762	            bool download_current_segment = read_type == ReadType::REMOTE_FS_READ_AND_PUT_IN_CACHE;
763	            if (download_current_segment)
764	            {
765	                bool need_complete_file_segment = file_segment->isDownloader();
766	                if (need_complete_file_segment)
767	                {
768	                    LOG_TEST(log, "Resetting downloader {} from scope exit", file_segment->getDownloader());
769	                    file_segment->completeBatchAndResetDownloader();
770	                }
771	            }
772	
773	            assert(!file_segment->isDownloader());
774	        }
775	        catch (...)
776	        {
777	            tryLogCurrentException(__PRETTY_FUNCTION__);
778	        }
779	    });
780	
781	    bytes_to_predownload = 0;
782	
783	    if (implementation_buffer)
784	    {
785	        bool can_read_further = updateImplementationBufferIfNeeded();
786	        if (!can_read_further)
787	            return false;
788	    }
789	    else
790	    {
791	        implementation_buffer = getImplementationBuffer(*current_file_segment_it);
792	
793	        if (read_type == ReadType::CACHED)
794	            (*current_file_segment_it)->incrementHitsCount();
795	    }
796	
797	    assert(!internal_buffer.empty());
798	    swap(*implementation_buffer);
799	
800	    auto & file_segment = *current_file_segment_it;
801	    auto current_read_range = file_segment->range();
802	
803	    LOG_TEST(
804	        log,
805	        "Current segment: {}, downloader: {}, current count: {}, position: {}",
806	        current_read_range.toString(),
807	        file_segment->getDownloader(),
808	        implementation_buffer->count(),
809	        implementation_buffer->getPosition());
810	
811	    assert(current_read_range.left <= file_offset_of_buffer_end);
812	    assert(current_read_range.right >= file_offset_of_buffer_end);
813	
814	    bool result = false;
815	    size_t size = 0;
816	
817	    size_t needed_to_predownload = bytes_to_predownload;
818	    if (needed_to_predownload)
819	    {
820	        predownload(file_segment);
821	
822	        result = implementation_buffer->hasPendingData();
823	        size = implementation_buffer->available();
824	    }
825	
826	    auto download_current_segment = read_type == ReadType::REMOTE_FS_READ_AND_PUT_IN_CACHE;
827	    if (download_current_segment != file_segment->isDownloader())
828	    {
829	        throw Exception(
830	            ErrorCodes::LOGICAL_ERROR,
831	            "Incorrect segment state. Having read type: {}, file segment info: {}",
832	            toString(read_type), file_segment->getInfoForLog());
833	    }
834	
835	    if (!result)
836	    {
837	#ifndef NDEBUG
838	        if (auto * cache_file_reader = dynamic_cast<ReadBufferFromFileDescriptor *>(implementation_buffer.get()))
839	        {
840	            auto cache_file_size = cache_file_reader->getFileSize();
841	            if (cache_file_size == 0)
842	                throw Exception(
843	                    ErrorCodes::LOGICAL_ERROR, "Attempt to read from an empty cache file: {} (just before actual read)", cache_file_size);
844	        }
845	#endif
846	
847	        Stopwatch watch(CLOCK_MONOTONIC);
848	
849	        result = implementation_buffer->next();
850	
851	        watch.stop();
852	        auto elapsed = watch.elapsedMicroseconds();
853	        current_file_segment_counters.increment(ProfileEvents::FileSegmentReadMicroseconds, elapsed);
854	
855	        size = implementation_buffer->buffer().size();
856	
857	        if (read_type == ReadType::CACHED)
858	        {
859	            ProfileEvents::increment(ProfileEvents::CachedReadBufferReadFromCacheBytes, size);
860	            ProfileEvents::increment(ProfileEvents::CachedReadBufferReadFromCacheMicroseconds, elapsed);
861	        }
862	        else
863	        {
864	            ProfileEvents::increment(ProfileEvents::CachedReadBufferReadFromSourceBytes, size);
865	            ProfileEvents::increment(ProfileEvents::CachedReadBufferReadFromSourceMicroseconds, elapsed);
866	        }
867	    }
868	
869	    if (result)
870	    {
871	        if (download_current_segment)
872	        {
873	            assert(file_offset_of_buffer_end + size - 1 <= file_segment->range().right);
874	
875	            bool success = file_segment->reserve(size);
876	            if (success)
877	            {
878	                assert(file_segment->getDownloadOffset() == static_cast<size_t>(implementation_buffer->getPosition()));
879	
880	                success = writeCache(implementation_buffer->position(), size, file_offset_of_buffer_end, *file_segment);
881	                if (success)
882	                {
883	                    assert(file_segment->getDownloadOffset() <= file_segment->range().right + 1);
884	                    assert(
885	                        std::next(current_file_segment_it) == file_segments_holder->file_segments.end()
886	                        || file_segment->getDownloadOffset() == implementation_buffer->getFileOffsetOfBufferEnd());
887	                }
888	                else
889	                {
890	                    assert(file_segment->state() == FileSegment::State::PARTIALLY_DOWNLOADED_NO_CONTINUATION);
891	                }
892	            }
893	            else
894	            {
895	                LOG_DEBUG(log, "No space left in cache, will continue without cache download");
896	                file_segment->complete(FileSegment::State::PARTIALLY_DOWNLOADED_NO_CONTINUATION);
897	            }
898	
899	            if (!success)
900	            {
901	                read_type = ReadType::REMOTE_FS_READ_BYPASS_CACHE;
902	                download_current_segment = false;
903	            }
904	        }
905	
906	        /// - If last file segment was read from remote fs, then we read up to segment->range().right, but
907	        /// the requested right boundary could be segment->range().left < requested_right_boundary <  segment->range().right.
908	        /// Therefore need to resize to a smaller size. And resize must be done after write into cache.
909	        /// - If last file segment was read from local fs, then we could read more than file_segemnt->range().right, so resize is also needed.
910	        if (std::next(current_file_segment_it) == file_segments_holder->file_segments.end())
911	        {
912	            size_t remaining_size_to_read = std::min(current_read_range.right, read_until_position - 1) - file_offset_of_buffer_end + 1;
913	            size = std::min(size, remaining_size_to_read);
914	            assert(implementation_buffer->buffer().size() >= nextimpl_working_buffer_offset + size);
915	            implementation_buffer->buffer().resize(nextimpl_working_buffer_offset + size);
916	        }
917	
918	        file_offset_of_buffer_end += size;
919	
920	    }
921	
922	    swap(*implementation_buffer);
923	
924	    current_file_segment_counters.increment(ProfileEvents::FileSegmentUsedBytes, available());
925	
926	    if (download_current_segment)
927	        file_segment->completeBatchAndResetDownloader();
928	
929	    assert(!file_segment->isDownloader());
930	
931	    LOG_TEST(
932	        log,
933	        "Key: {}. Returning with {} bytes, buffer position: {} (offset: {}, predownloaded: {}), "
934	        "buffer available: {}, current range: {}, current offset: {}, file segment state: {}, download offset: {}, read_type: {}, "
935	        "reading until position: {}, started with offset: {}, remaining ranges: {}",
936	        getHexUIntLowercase(cache_key),
937	        working_buffer.size(),
938	        getPosition(),
939	        offset(),
940	        needed_to_predownload,
941	        available(),
942	        current_read_range.toString(),
943	        file_offset_of_buffer_end,
944	        FileSegment::stateToString(file_segment->state()),
945	        file_segment->getDownloadOffset(),
946	        toString(read_type),
947	        read_until_position,
948	        first_offset,
949	        file_segments_holder->toString());
950	
951	    if (size == 0 && file_offset_of_buffer_end < read_until_position)
952	    {
953	        std::optional<size_t> cache_file_size;
954	        if (auto * cache_file_reader = dynamic_cast<ReadBufferFromFileDescriptor *>(implementation_buffer.get()))
955	            cache_file_size = cache_file_reader->getFileSize();
956	
957	        throw Exception(
958	            ErrorCodes::LOGICAL_ERROR,
959	            "Having zero bytes, but range is not finished: file offset: {}, reading until: {}, read type: {}, cache file size: {}",
960	            file_offset_of_buffer_end,
961	            read_until_position,
962	            toString(read_type),
963	            cache_file_size ? std::to_string(*cache_file_size) : "None");
964	    }
965	
966	    return result;
967	}
