969	off_t CachedReadBufferFromRemoteFS::seek(off_t offset, int whence)
970	{
971	    if (initialized)
972	        throw Exception(ErrorCodes::CANNOT_SEEK_THROUGH_FILE, "Seek is allowed only before first read attempt from the buffer");
973	
974	    if (whence != SEEK_SET)
975	        throw Exception(ErrorCodes::CANNOT_SEEK_THROUGH_FILE, "Only SEEK_SET allowed");
976	
977	    first_offset = offset;
978	    file_offset_of_buffer_end = offset;
979	    size_t size = getTotalSizeToRead();
980	    initialize(offset, size);
981	
982	    return offset;
983	}
984	
985	size_t CachedReadBufferFromRemoteFS::getTotalSizeToRead()
986	{
987	    /// Last position should be guaranteed to be set, as at least we always know file size.
988	    if (!read_until_position)
989	        throw Exception(ErrorCodes::LOGICAL_ERROR, "Last position was not set");
990	
991	    /// On this level should be guaranteed that read size is non-zero.
992	    if (file_offset_of_buffer_end >= read_until_position)
993	        throw Exception(
994	            ErrorCodes::LOGICAL_ERROR, "Read boundaries mismatch. Expected {} < {}", file_offset_of_buffer_end, read_until_position);
995	
996	    return read_until_position - file_offset_of_buffer_end;
997	}
998	
999	void CachedReadBufferFromRemoteFS::setReadUntilPosition(size_t)
1000	{
